// Real-tensor testbench for bpu_sa_sram_wrapper: runs the commands of
// bpu_sa_golden_vectors_pkg (real Qwen3.5-2B tensors, requantized to the unit's INT8/INT4
// + bf16-per-16 format) against sram_arbiter_matrix_model and checks every C element
// written, bit for bit, against the golden model's prediction of the arithmetic contract.
//
// The package is generated by the golden model in SiliconBadgers/verification
// (models/golden_kquant, tools/export_rtl_vectors.py): a memory image in the wrapper's SRAM layout, the command
// list (block-scaled INT4 and INT8 tiles with K = 2048, the INT4 tile split in two chained
// commands, an unscaled INT8 tile) and the expected C of each command.
//
// Parameters: Latency, ReadyPct (the model), Seed. The wrapper is 8 x 8, AccW 32,
// DataW 4096, BlockK 16, INT4 and block scaling on, matching the package.
// Plusargs:
//   +seed=<n>       seed for the model's ready and garbage generator (default: Seed)
//   +inject_error=1 corrupt one expected value on purpose; the run must FAIL
//
// Checks: every C element of every command that writes; a command that keeps its sums
// writes nothing; done_o without err_o, busy_o high until done_o; the model's port checks.
// The run fails unless every command completed and all C elements were checked, and (when
// the arbiter isn't always ready) request stalls occurred. It prints one RESULT line for
// the regression runner (tb/compute/Matrix_Unit/run_tests.sh).
module bpu_sa_sram_wrapper_golden_tb;
  import bpu_sa_golden_vectors_pkg::*;

  parameter int Latency = 4;
  parameter int ReadyPct = 70;
  parameter int Seed = 1;

  localparam int ROWS = GV_ROWS;
  localparam int COLS = GV_COLS;
  localparam int DATA_W = 8 * GV_ROW_BYTES;
  localparam int ADDR_WIDTH = 32;
  localparam int K_WIDTH = 16;
  localparam int SIZE_W = $clog2(GV_ROW_BYTES) + 1;
  localparam int MEM_BYTES = GV_MEM_ROWS * GV_ROW_BYTES;
  localparam int CMD_TIMEOUT = (2048 * (Latency + 4) + 400) * 100 / ReadyPct;
  localparam int TIMEOUT_CYCLES = (GV_COMMANDS + 2) * CMD_TIMEOUT;

  logic clk;
  logic rst_n;

  logic cmd_valid;
  logic cmd_ready;
  logic [ADDR_WIDTH-1:0] cmd_a_addr;
  logic [ADDR_WIDTH-1:0] cmd_b_addr;
  logic [ADDR_WIDTH-1:0] cmd_c_addr;
  logic [ADDR_WIDTH-1:0] cmd_sa_addr;
  logic [ADDR_WIDTH-1:0] cmd_sb_addr;
  logic [K_WIDTH-1:0] cmd_k;
  logic cmd_int4;
  logic cmd_scaled;
  logic cmd_clear_acc;
  logic cmd_write_output;
  logic busy;
  logic done;
  logic err;

  logic req_valid;
  logic req_ready;
  logic req_is_write;
  logic [SIZE_W-1:0] req_size;
  logic [ADDR_WIDTH-1:0] req_addr;
  logic [DATA_W-1:0] req_wdata;
  logic rsp_valid;
  logic [DATA_W-1:0] rsp_rdata;

  logic [3:0][ADDR_WIDTH-1:0] rd_lo;
  logic [3:0][ADDR_WIDTH-1:0] rd_hi;
  logic [ADDR_WIDTH-1:0] c_lo;
  logic [ADDR_WIDTH-1:0] c_hi;
  int reads;
  int writes;
  int read_bytes;
  int write_bytes;
  int model_errors;
  int req_stalls;
  int in_flight;

  int cycle;
  int seed;
  int inject_arg;
  bit inject_error;
  int errors;
  int commands_done;
  int c_checked;
  int c_expected;
  int kept_checked;
  int busy_cycles;
  string status;

  bpu_sa_sram_wrapper #(
    .Rows     (ROWS),
    .Cols     (COLS),
    .AccW     (32),
    .AddrW    (ADDR_WIDTH),
    .DataW    (DATA_W),
    .SizeW    (SIZE_W),
    .KW       (K_WIDTH),
    .BufRows  (2),
    .WriteAcks(1'b0),
    .Int4     (1'b1),
    .Scale    (1'b1),
    .BlockK   (GV_BLOCK_K)
  ) u_dut (
    .clk_i                  (clk),
    .rst_ni                 (rst_n),
    .cmd_valid_i            (cmd_valid),
    .cmd_ready_o            (cmd_ready),
    .cmd_a_addr_i           (cmd_a_addr),
    .cmd_b_addr_i           (cmd_b_addr),
    .cmd_c_addr_i           (cmd_c_addr),
    .cmd_sa_addr_i          (cmd_sa_addr),
    .cmd_sb_addr_i          (cmd_sb_addr),
    .cmd_k_i                (cmd_k),
    .cmd_int4_i             (cmd_int4),
    .cmd_scaled_i           (cmd_scaled),
    .cmd_clear_acc_i        (cmd_clear_acc),
    .cmd_write_output_i     (cmd_write_output),
    .busy_o                 (busy),
    .done_o                 (done),
    .err_o                  (err),
    .matrix_req_valid_o     (req_valid),
    .matrix_req_ready_i     (req_ready),
    .matrix_req_is_write_o  (req_is_write),
    .matrix_req_size_bytes_o(req_size),
    .matrix_req_addr_o      (req_addr),
    .matrix_req_wdata_o     (req_wdata),
    .matrix_rsp_valid_i     (rsp_valid),
    .matrix_rsp_rdata_i     (rsp_rdata)
  );

  sram_arbiter_matrix_model #(
    .AddrW    (ADDR_WIDTH),
    .DataW    (DATA_W),
    .SizeW    (SIZE_W),
    .MemBytes (MEM_BYTES),
    .Latency  (Latency),
    .ReadyPct (ReadyPct),
    .WriteAcks(1'b0)
  ) u_sram (
    .clk_i           (clk),
    .rst_ni          (rst_n),
    .req_valid_i     (req_valid),
    .req_ready_o     (req_ready),
    .req_is_write_i  (req_is_write),
    .req_size_bytes_i(req_size),
    .req_addr_i      (req_addr),
    .req_wdata_i     (req_wdata),
    .rsp_valid_o     (rsp_valid),
    .rsp_rdata_o     (rsp_rdata),
    .rd_lo_i         (rd_lo),
    .rd_hi_i         (rd_hi),
    .c_lo_i          (c_lo),
    .c_hi_i          (c_hi),
    .reads_o         (reads),
    .writes_o        (writes),
    .read_bytes_o    (read_bytes),
    .write_bytes_o   (write_bytes),
    .errors_o        (model_errors),
    .stalls_o        (req_stalls),
    .in_flight_o     (in_flight)
  );

  initial begin : clock
    clk = 1'b0;
    forever begin
      #5 clk = ~clk;
    end
  end

  initial begin : watchdog
    repeat (TIMEOUT_CYCLES) begin
      @(posedge clk);
    end
    $fatal(1, "bpu_sa_sram_wrapper_golden_tb: timeout after %0d cycles", TIMEOUT_CYCLES);
  end

  task automatic tick();
    @(negedge clk);
    cycle++;
    if (err === 1'b1 && done !== 1'b1) begin
      errors++;
      $display("bpu_sa_sram_wrapper_golden_tb: err_o without done_o at cycle %0d", cycle);
    end
  endtask

  // Run command n to completion and check what it wrote.
  task automatic run_command(input int n);
    int unsigned c;
    int waited;
    int writes0;
    logic [31:0] got;
    logic [31:0] want;

    c       = GV_CMD[n][9];
    writes0 = writes;
    // Reads anywhere in the image; writes only in this command's C, when it writes.
    for (int s = 0; s < 4; s++) begin
      rd_lo[s] = '0;
      rd_hi[s] = ADDR_WIDTH'(MEM_BYTES);
    end
    c_lo             = (GV_CMD[n][4] != 0) ? ADDR_WIDTH'(c) : '0;
    c_hi             = (GV_CMD[n][4] != 0) ? ADDR_WIDTH'(c + 4 * ROWS * COLS) : '0;

    cmd_valid        = 1'b1;
    cmd_k            = K_WIDTH'(GV_CMD[n][0]);
    cmd_int4         = GV_CMD[n][1][0];
    cmd_scaled       = GV_CMD[n][2][0];
    cmd_clear_acc    = GV_CMD[n][3][0];
    cmd_write_output = GV_CMD[n][4][0];
    cmd_a_addr       = ADDR_WIDTH'(GV_CMD[n][5]);
    cmd_b_addr       = ADDR_WIDTH'(GV_CMD[n][6]);
    cmd_sa_addr      = ADDR_WIDTH'(GV_CMD[n][7]);
    cmd_sb_addr      = ADDR_WIDTH'(GV_CMD[n][8]);
    cmd_c_addr       = ADDR_WIDTH'(c);
    while (cmd_ready !== 1'b1) begin
      tick();
    end
    tick();  // accepted on this rising edge
    cmd_valid = 1'b0;

    waited    = 1;
    while (done !== 1'b1) begin
      if (busy !== 1'b1) begin
        errors++;
        $display("bpu_sa_sram_wrapper_golden_tb: busy_o low before done_o (command %0d)", n);
      end
      if (waited > CMD_TIMEOUT) begin
        $fatal(1, "bpu_sa_sram_wrapper_golden_tb: command %0d did not finish", n);
      end
      tick();
      waited++;
    end
    busy_cycles += waited;
    if (err !== 1'b0) begin
      errors++;
      $display("bpu_sa_sram_wrapper_golden_tb: command %0d done with err_o", n);
    end
    if (in_flight != 0 || rsp_valid !== 1'b0) begin
      errors++;
      $display("bpu_sa_sram_wrapper_golden_tb: command %0d done with reads in flight", n);
    end
    $display("CMD %0d k=%0d int4=%0d scaled=%0d clear=%0d write=%0d cycles=%0d", n, GV_CMD[n][0],
             GV_CMD[n][1], GV_CMD[n][2], GV_CMD[n][3], GV_CMD[n][4], waited);
    commands_done++;

    if (GV_CMD[n][4] == 0) begin
      kept_checked++;
      if (writes != writes0) begin
        errors++;
        $display("bpu_sa_sram_wrapper_golden_tb: command %0d kept its sums but wrote C", n);
      end
      return;
    end
    for (int e = 0; e < ROWS * COLS; e++) begin
      for (int b = 0; b < 4; b++) begin
        got[8*b+:8] = u_sram.mem[c+4*e+b];
      end
      want = GV_C[n][e];
      if (inject_error && n == 0 && e == 0) begin
        want = want ^ 32'h1;
      end
      c_checked++;
      if (got !== want) begin
        errors++;
        if (errors <= 10) begin
          $display("bpu_sa_sram_wrapper_golden_tb: MISMATCH cmd %0d C[%0d][%0d] got %h want %h", n,
                   e / COLS, e % COLS, got, want);
        end
      end
    end
  endtask

  initial begin : main
    if (!$value$plusargs("seed=%d", seed)) begin
      seed = Seed;
    end
    if (!$value$plusargs("inject_error=%d", inject_arg)) begin
      inject_arg = 0;
    end
    inject_error  = (inject_arg != 0);
    errors        = 0;
    commands_done = 0;
    c_checked     = 0;
    kept_checked  = 0;
    busy_cycles   = 0;
    cycle         = 0;
    c_expected    = 0;
    for (int n = 0; n < GV_COMMANDS; n++) begin
      c_expected += (GV_CMD[n][4] != 0) ? ROWS * COLS : 0;
    end

    rst_n            = 1'b0;
    cmd_valid        = 1'b0;
    cmd_k            = '0;
    cmd_int4         = 1'b0;
    cmd_scaled       = 1'b0;
    cmd_clear_acc    = 1'b1;
    cmd_write_output = 1'b1;
    cmd_a_addr       = '0;
    cmd_b_addr       = '0;
    cmd_c_addr       = '0;
    cmd_sa_addr      = '0;
    cmd_sb_addr      = '0;
    rd_lo            = '0;
    rd_hi            = '0;
    c_lo             = '0;
    c_hi             = '0;
    for (int r = 0; r < GV_MEM_ROWS; r++) begin
      for (int b = 0; b < GV_ROW_BYTES; b++) begin
        u_sram.mem[r*GV_ROW_BYTES+b] = GV_MEM[r][8*b+:8];
      end
    end
    // Stale C regions hold a pattern no expected value has, so a missing write shows.
    for (int a = GV_C_LO; a < GV_C_HI; a++) begin
      u_sram.mem[a] = 8'hA5;
    end
    repeat (2) begin
      @(negedge clk);
    end
    rst_n = 1'b1;
    tick();

    for (int n = 0; n < GV_COMMANDS; n++) begin
      run_command(n);
      repeat (3) begin
        tick();
      end
    end

    if (errors != 0 || model_errors != 0 || commands_done != GV_COMMANDS
        || c_checked != c_expected || kept_checked == 0
        || (ReadyPct < 100 && req_stalls == 0)) begin
      status = "FAIL";
    end else begin
      status = "PASS";
    end
    $write("RESULT bpu_sa_sram_wrapper_golden_tb latency=%0d ready_pct=%0d seed=%0d", Latency,
           ReadyPct, seed);
    $write(" commands=%0d c_checked=%0d kept=%0d busy_cycles=%0d", commands_done, c_checked,
           kept_checked, busy_cycles);
    $write(" reads=%0d writes=%0d read_bytes=%0d write_bytes=%0d", reads, writes, read_bytes,
           write_bytes);
    $display(" req_stalls=%0d model_errors=%0d errors=%0d status=%s", req_stalls, model_errors,
             errors, status);
    if (status != "PASS") begin
      $fatal(1, "bpu_sa_sram_wrapper_golden_tb: FAIL (%0d errors, %0d model errors)", errors,
             model_errors);
    end
    $finish;
  end

endmodule
